// Recorder endurance index — record JAH-GPC-DICTAPHONE-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"storage_h": 200, "battery_h": 30, "price_usd": 250};
var value = (m.storage_h*m.battery_h/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-DICTAPHONE-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-DICTAPHONE-000001|' + value.toFixed(2) + ' endurance index');

